import json
from pathlib import Path

import gradio as gr
import joblib
import numpy as np


ROOT = Path(__file__).resolve().parents[1]
MAIN_MODEL_PATH = ROOT / "models" / "best_model.joblib"
MAIN_LABEL_ENCODER_PATH = ROOT / "models" / "label_encoder.joblib"
MAIN_MODEL_INFO_PATH = ROOT / "models" / "model_info.json"
AI_TFIDF_MODEL_PATH = ROOT / "models" / "v2_ai_tfidf" / "best_model.joblib"
BACKGROUND_VIDEO_PATH = ROOT / "app" / "assets" / "background.mp4"
BACKGROUND_FALLBACK_PATH = ROOT / "app" / "assets" / "background_fallback.jpg"


with open(MAIN_MODEL_INFO_PATH, "r", encoding="utf-8") as f:
    MAIN_MODEL_INFO = json.load(f)

MAIN_CLASSIFIER = None
MAIN_LABEL_ENCODER = None
AI_TFIDF_CLASSIFIER = None
EMBEDDER = None

AI_LABELS = {"chatgpt", "claude", "deepseek", "gemini", "grok"}
HUMAN_LABELS = {"human_original", "human_ai_polished"}
MAIN_MODE = "Human vs AI source model"
AI_ONLY_MODE = "AI-model attribution model"


def display_label(label):
    names = {
        "chatgpt": "ChatGPT",
        "claude": "Claude",
        "deepseek": "DeepSeek",
        "gemini": "Gemini",
        "grok": "Grok",
        "human_ai_polished": "Human + AI polished",
        "human_original": "Human original",
    }
    return names.get(label, label)


def get_embedder():
    global EMBEDDER
    if EMBEDDER is None:
        from sentence_transformers import SentenceTransformer

        EMBEDDER = SentenceTransformer(MAIN_MODEL_INFO["embedding_model"])
    return EMBEDDER


def get_main_classifier():
    global MAIN_CLASSIFIER, MAIN_LABEL_ENCODER
    if MAIN_CLASSIFIER is None:
        MAIN_CLASSIFIER = joblib.load(MAIN_MODEL_PATH)
    if MAIN_LABEL_ENCODER is None:
        MAIN_LABEL_ENCODER = joblib.load(MAIN_LABEL_ENCODER_PATH)
    return MAIN_CLASSIFIER, MAIN_LABEL_ENCODER


def get_ai_tfidf_classifier():
    global AI_TFIDF_CLASSIFIER
    if AI_TFIDF_CLASSIFIER is None:
        AI_TFIDF_CLASSIFIER = joblib.load(AI_TFIDF_MODEL_PATH)
    return AI_TFIDF_CLASSIFIER


def probability_scores(classifier, features):
    if hasattr(classifier, "predict_proba"):
        return classifier.predict_proba(features)[0]

    scores = classifier.decision_function(features)
    if np.ndim(scores) == 1:
        scores = np.column_stack([-scores, scores])
    scores = scores[0]
    exp_scores = np.exp(scores - np.max(scores))
    return exp_scores / exp_scores.sum()


def format_top_scores(labels, probabilities, top_n=5):
    top_indices = np.argsort(probabilities)[::-1][:top_n]
    return {
        display_label(labels[idx]): float(probabilities[idx])
        for idx in top_indices
    }


def scores_html(labels, probabilities, top_n=5):
    top_indices = np.argsort(probabilities)[::-1][:top_n]
    rows = []
    for idx in top_indices:
        label = display_label(labels[idx])
        pct = float(probabilities[idx]) * 100
        rows.append(
            f"""
            <div class=\"score-row\">
              <div class=\"score-meta\">
                <span>{label}</span>
                <strong>{pct:.1f}%</strong>
              </div>
              <div class=\"score-track\">
                <div class=\"score-fill\" style=\"width: {max(1, pct):.1f}%\"></div>
              </div>
            </div>
            """
        )
    winner = display_label(labels[top_indices[0]])
    return f"""
    <div class=\"scores-card\">
      <div class=\"scores-title\">Model probabilities</div>
      <div class=\"scores-winner\">{winner}</div>
      {''.join(rows)}
    </div>
    """


def predict_main_source(text):
    classifier, label_encoder = get_main_classifier()
    embedder = get_embedder()
    embedding = embedder.encode(
        [text],
        normalize_embeddings=True,
        show_progress_bar=False,
    )
    probabilities = probability_scores(classifier, embedding)
    labels = label_encoder.classes_
    top_indices = np.argsort(probabilities)[::-1]
    top_label = labels[top_indices[0]]
    top_confidence = float(probabilities[top_indices[0]])

    ai_likelihood = sum(
        float(probabilities[idx])
        for idx, label in enumerate(labels)
        if label in AI_LABELS
    )
    human_like_likelihood = sum(
        float(probabilities[idx])
        for idx, label in enumerate(labels)
        if label in HUMAN_LABELS
    )

    prediction = (
        f"Most similar writing style: {display_label(top_label)}\n\n"
        f"Confidence: {top_confidence:.1%}\n\n"
        f"AI-model likelihood: {ai_likelihood:.1%}\n"
        f"Human-like likelihood: {human_like_likelihood:.1%}"
    )

    limitations = (
        "This mode uses sentence embeddings and compares the text with seven source/style "
        "classes from the custom dataset: five AI models, one human author, and AI-polished "
        "human writing. It is a writing-style similarity classifier, not proof of authorship. "
        "Predictions may be less reliable for very short texts, heavily edited text, topics "
        "outside the training data, or AI models not included in the dataset."
    )

    return prediction, scores_html(labels, probabilities, top_n=3), explanation_html(limitations)


def predict_ai_model(text):
    classifier = get_ai_tfidf_classifier()
    probabilities = probability_scores(classifier, [text])
    labels = classifier.classes_
    top_indices = np.argsort(probabilities)[::-1]
    top_label = labels[top_indices[0]]
    top_confidence = float(probabilities[top_indices[0]])

    prediction = (
        f"Most likely AI model: {display_label(top_label)}\n\n"
        f"Confidence: {top_confidence:.1%}\n\n"
        "This mode assumes the text was generated by one of the five AI models in the "
        "training dataset."
    )

    limitations = (
        "This mode uses character n-gram TF-IDF, which is strong for local writing patterns "
        "such as punctuation, phrasing, formatting habits, and repeated stylistic choices. "
        "It should not be used as proof of authorship. Results may change if the text was "
        "edited, paraphrased, translated, reformatted, produced by a newer model version, "
        "or written by a model outside the five trained labels."
    )

    return prediction, scores_html(labels, probabilities, top_n=5), explanation_html(limitations)


def predict_source(mode, text):
    text = text.strip()
    if not text:
        return "Please paste some text first.", scores_html(np.array(["No result"]), np.array([1.0]), top_n=1), explanation_html("No text was provided.")

    if mode == AI_ONLY_MODE:
        return predict_ai_model(text)
    return predict_main_source(text)


def selected_system_html(mode):
    if mode == AI_ONLY_MODE:
        title = "Selected: System 2 - AI-model attribution"
        body = "Use this when the text is assumed to come from ChatGPT, Claude, DeepSeek, Gemini, or Grok."
    else:
        title = "Selected: System 1 - Human vs AI source"
        body = "Use this first when you want to compare human original, AI-polished, and AI-generated writing."
    return f"""
    <div class=\"selected-system\">
      <strong>{title}</strong>
      <span>{body}</span>
    </div>
    """


def choose_main_mode():
    return MAIN_MODE, selected_system_html(MAIN_MODE)


def choose_ai_mode():
    return AI_ONLY_MODE, selected_system_html(AI_ONLY_MODE)


def explanation_html(text):
    return f"""
    <div class=\"explanation-card\">
      <strong>Classifier explanation</strong>
      <p>{text}</p>
    </div>
    """


